INSERT INTO entity_citations
  (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order)
VALUES
('CIT_CHAYYLIEL_3EN','ENT_JM_CHAYYLIEL','SRC_3_ENOCH','3 Enoch (The Hebrew Book of Enoch)','3 Enoch','And why is he called CHAYYLIEL H''? Because he is appointed over the Holy Chayyoth and smites the Chayyoth with lashes of fire','Hugo Odeberg',1928,'https://archive.org/details/HebrewBookOfEnochenoch3',NULL,'primary-verbatim',NULL,true,'Located by name in 3 Enoch (Odeberg); verify the chapter.',DATE '2026-06-25','name-anchored + substring gate against Odeberg 3 Enoch',1),
('CIT_ZAZRIEL_3EN','ENT_JM_ZAZRIEL','SRC_3_ENOCH','3 Enoch (The Hebrew Book of Enoch)','3 Enoch','And Zazriel H'', the prince, when he sees GEBURATIEL H'', the prince, he removes the crown of glory from his head and falls on his face.','Hugo Odeberg',1928,'https://archive.org/details/HebrewBookOfEnochenoch3',NULL,'primary-verbatim',NULL,true,'Located by name in 3 Enoch (Odeberg); verify the chapter.',DATE '2026-06-25','name-anchored + substring gate against Odeberg 3 Enoch',1),
('CIT_GEBURATIEL_3EN','ENT_JM_GEBURATIEL','SRC_3_ENOCH','3 Enoch (The Hebrew Book of Enoch)','3 Enoch','And Geburatiel H'', the prince, when he sees ''ARAPHIEL H'', the prince, he removes the crown of glory from his head and falls on his face.','Hugo Odeberg',1928,'https://archive.org/details/HebrewBookOfEnochenoch3',NULL,'primary-verbatim',NULL,true,'Located by name in 3 Enoch (Odeberg); verify the chapter.',DATE '2026-06-25','name-anchored + substring gate against Odeberg 3 Enoch',1),
('CIT_SOPHERIEL_3EN','ENT_JM_SOPHERIEL','SRC_3_ENOCH','3 Enoch (The Hebrew Book of Enoch)','3 Enoch','Why is he called Sopheriel H'' who killeth (Sopheriel H'' the Killer)? Because he is appointed over the books of the dead : [so that] everyone, when the day of his death draws nigh','Hugo Odeberg',1928,'https://archive.org/details/HebrewBookOfEnochenoch3',NULL,'primary-verbatim',NULL,true,'Located by name in 3 Enoch (Odeberg); verify the chapter.',DATE '2026-06-25','name-anchored + substring gate against Odeberg 3 Enoch',1),
('CIT_BARATTIEL_3EN','ENT_JM_BARATTIEL','SRC_3_ENOCH','3 Enoch (The Hebrew Book of Enoch)','3 Enoch','And Barattiel, the great prince, when he sees HAMON, the great prince, the fearful and honoured, pleasant and terrible one who maketh all the children of heaven to tremble, when the time draweth nigh (that is set) for the saying of the ''(Thrice) Holy'', as it is written (Isa.','Hugo Odeberg',1928,'https://archive.org/details/HebrewBookOfEnochenoch3',NULL,'primary-verbatim',NULL,true,'Located by name in 3 Enoch (Odeberg); verify the chapter.',DATE '2026-06-25','name-anchored + substring gate against Odeberg 3 Enoch',1),
('CIT_AZBOGAH_3EN','ENT_JM_AZBOGAH','SRC_3_ENOCH','3 Enoch (The Hebrew Book of Enoch)','3 Enoch','Why is he called ''Azbuga? Because in the future he will gird (clothe) the righteous and pious of the world with the garments of life and wrap them in the cloak of life, that they may live in them an eternal life. (23) And when he sees the two great princes, the strong and glorified ones who are standing above him, he removes the crown of glory from his head and falls on his face.','Hugo Odeberg',1928,'https://archive.org/details/HebrewBookOfEnochenoch3',NULL,'primary-verbatim',NULL,true,'Located by name in 3 Enoch (Odeberg); verify the chapter.',DATE '2026-06-25','name-anchored + substring gate against Odeberg 3 Enoch',1),
('CIT_PLOTO_THEOG','ENT_PLOTO','SRC_HESIOD_THEOGONY','Hesiod, Theogony','Theogony 240-264','Ploto, Eucrante, Sao, and Amphitrite, and Eudora, and Thetis, Galene and Glauce, Cymothoe, Speo, Thoe and lovely Halie, and Pasithea, and Erato, and rosy-armed Eunice, and gracious Melite, and Eulimene, and Agaue, Doto, Proto, Pherusa, and Dynamene, and Nisaea, and Actaea, and Protomedea, Doris, Panopea, and comely Galatea, and lovely Hippothoe, and rosy-armed Hipponoe, and Cymodoce who with Cymatolege and Amphitrite easily calms the waves upon the misty sea and the blasts of raging winds, and Cymo, and Eione, and rich-crowned Alimede, and Glauconome, fond of laughter, and Pontoporea, Leagore, Euagore, and Laomedea, and Polynoe, and Autonoe, and Lysianassa, and Euarne, lovely of shape and without blemish of form, and Psamathe of charming figure and divine Menippe, Neso, Eupompe, Themisto, Pronoe, and Nemertes who has the nature of her deathless father.','Hugh G. Evelyn-White',1914,'https://www.gutenberg.org/ebooks/348',NULL,'primary-verbatim',NULL,true,'Named in the Nereid catalogue of the Theogony (Evelyn-White); verify the line.',DATE '2026-06-25','name-anchored + substring gate against Evelyn-White Theogony (Gutenberg #348)',1),
