-- scripts/add_3enoch_nereids.sql
-- Mainstream pass (3): 3 Enoch angelic princes + Hesiod Nereid catalogue.
-- Verbatim, substring-gated (Odeberg 1928 / Evelyn-White 1914). No AI prose.

BEGIN;

ON CONFLICT (entity_id) DO NOTHING;

SELECT 'ENT_JM_AZBOGAH','Azbuga','variant','en','SRC_3_ENOCH','high','candidate_verified_name','Spelling in Odeberg 3 Enoch.' WHERE NOT EXISTS (SELECT 1 FROM entity_aliases WHERE entity_id='ENT_JM_AZBOGAH' AND alias_name='Azbuga');

ON CONFLICT (citation_id) DO UPDATE SET quote=EXCLUDED.quote, locus=EXCLUDED.locus;

COMMIT;
